export function Questionnaire({
  questions,
  onComplete,
}: {
  questions: { id: string; title: string; options: string[] }[];
  onComplete: (answers: Record<string, string>) => void;
}) {
  const [step, setStep] = React.useState(0),
    [answers, setAnswers] = React.useState<Record<string, string>>({});
  const q = questions[step];
  if (!q) return <p>No questions configured.</p>;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!answers[q.id]) return;
        if (step === questions.length - 1) onComplete(answers);
        else setStep(step + 1);
      }}
      className="space-y-6"
    >
      <Progress label="Your progress" value={(step / questions.length) * 100} />
      <h3 className="font-editorial text-2xl">{q.title}</h3>
      <RadioGroup
        label={q.title}
        value={answers[q.id] || ""}
        onValueChange={(value) => setAnswers((a) => ({ ...a, [q.id]: value }))}
        options={q.options.map((o) => ({ label: o, value: o }))}
      />
      <div className="flex gap-3">
        <Button
          tone="outline"
          disabled={!step}
          onClick={() => setStep(step - 1)}
        >
          Previous
        </Button>
        <Button type="submit" disabled={!answers[q.id]}>
          {step === questions.length - 1 ? "Finish" : "Next"}
        </Button>
      </div>
    </form>
  );
}

import * as React from "react";
import { LoaderCircle } from "lucide-react";
import { cx } from "./utils";
export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  tone?: "primary" | "secondary" | "outline" | "quiet" | "danger" | "accent";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "primary",
      size = "md",
      loading = false,
      disabled,
      children,
      className,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        ref={ref}
        type={type}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        className={cx(
          "a-button",
          {
            "bg-ink text-paper hover:bg-ink/85": tone === "primary",
            "bg-surface text-ink hover:bg-surface/70": tone === "secondary",
            "border border-line bg-transparent text-ink": tone === "outline",
            "bg-transparent text-ink hover:bg-surface": tone === "quiet",
          "bg-danger text-on-danger": tone === "danger",
            "bg-gold text-[#181818]": tone === "accent",
          },
          {
            "min-h-9 px-3 text-xs": size === "sm",
            "min-h-11 px-4 text-sm": size === "md",
            "min-h-13 px-6 text-base": size === "lg",
          },
          className,
        )}
        {...props}
      >
        {loading && (
          <LoaderCircle
            className="size-4 animate-spin motion-reduce:animate-none"
            aria-hidden
          />
        )}
        {children}
      </button>
    );
  },
);
