              >
                <SE.ItemText>{o.label}</SE.ItemText>
                <SE.ItemIndicator>
                  <Check className="size-3.5" />
                </SE.ItemIndicator>
              </SE.Item>
            ))}
          </SE.Viewport>
        </SE.Content>
      </SE.Portal>
